-- ==============================================================================
-- Kahoot-style 6-digit join PINs (100000-999999), generated by the database.
-- Replaces the 5-digit codes; existing events get new PINs (old 5-digit links stop working).
-- The internal event id (uuid) is unchanged, so posts, votes and R2 file paths are unaffected.
-- ==============================================================================

-- 1. Unique random 6-digit PIN
CREATE OR REPLACE FUNCTION public.generate_join_code()
RETURNS text
LANGUAGE plpgsql
VOLATILE
SET search_path = public
AS $$
DECLARE
  candidate text;
BEGIN
  LOOP
    candidate := (floor(random() * 900000) + 100000)::int::text;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM events WHERE join_code = candidate);
  END LOOP;
  RETURN candidate;
END;
$$;

-- 2. Re-number existing events (the "never change" rule is paused only for this one-off migration)
ALTER TABLE public.events DROP CONSTRAINT IF EXISTS events_join_code_5_digits;
ALTER TABLE public.events DISABLE TRIGGER events_join_code_immutable;

DO $$
DECLARE
  ev record;
BEGIN
  FOR ev IN SELECT id FROM public.events WHERE join_code !~ '^[0-9]{6}$' LOOP
    UPDATE public.events SET join_code = public.generate_join_code() WHERE id = ev.id;
  END LOOP;
END $$;

ALTER TABLE public.events ENABLE TRIGGER events_join_code_immutable;

-- 3. Only 6-digit PINs are valid from now on
ALTER TABLE public.events DROP CONSTRAINT IF EXISTS events_join_code_6_digits;
ALTER TABLE public.events ADD CONSTRAINT events_join_code_6_digits CHECK (join_code ~ '^[0-9]{6}$');
